import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

type Entry = [howTo: string, formula: string, example: string, question: string, answer: string];
type Copy = { salary: Entry; vat: Entry; ruling: Entry };

const copy: Record<SupportedLocale, Copy> = {
  ko: {
    salary: ["연봉 또는 월급과 별도 기여금 가정률을 입력하세요. 2026년 AOW 미도달자의 Box 1 첫 구간은 국민보험료를 포함하며, 이 계산기는 세액공제와 나이를 반영하지 않습니다.", "연간 세금=38,883유로까지 35.75% + 다음 39,543유로까지 37.56% + 초과분 49.5%(2026 AOW 미도달 기준). 추정 순액=연봉−세금−입력 기여금.", "연봉 €50,000, 별도 기여금률 0%이면 세금 €18,076.22, 추정 연 순액 €31,923.78(월 €2,660.32)입니다. 세액공제는 제외했습니다.", "이 결과가 실제 월급명세서와 같나요?", "아닙니다. 나이/AOW 구간, 세액공제, 공제 항목과 개인 사정을 모델링하지 않습니다. 0%는 별도 기여금 입력값일 뿐 실제 부담이 없다는 뜻이 아닙니다."],
    vat: ["세전 금액 또는 세후 합계와 계산 방향을 고르고 해당 거래에 맞는 BTW 비율을 입력하세요. 품목·면세·역과세·지역 분류는 직접 확인해야 합니다.", "세전 VAT=세전 금액×입력률/100; 세후 합계=세전 금액+VAT. 세후 입력이면 세전 금액=합계/(1+입력률/100).", "세전 €1,000에 21%를 입력하면 BTW €210, 합계 €1,210입니다. 세후 €1,210에서 21%를 빼면 세전 €1,000입니다.", "네덜란드 거래는 모두 21%인가요?", "아닙니다. 일반 21%, 일부 재화·서비스 9%, 특정 국제거래 등 0%와 면세가 있습니다. 도구는 거래 자격을 판정하지 않습니다."],
    ruling: ["연간 총급여와 시나리오 비율을 입력하세요. 결과는 자격 승인이나 세금 판정이 아니라 비율 계산이며, 2026 연간 상한은 €78,600입니다.", "잠재 면세 수당=최솟값(연봉×입력률/100, €78,600); 남는 급여=연봉−수당. 전체 연도 가정의 엔진 산식입니다.", "연봉 €80,000에 30%를 입력하면 잠재 수당 €24,000, 남는 급여 €56,000입니다. 이는 승인·자격 확인을 뜻하지 않습니다.", "입력만으로 30% facility 자격이 확인되나요?", "아닙니다. 2026 급여 기준은 일반적으로 €48,013 초과이며 연령·학위 등 예외, 해외 채용, 거주 이력, 고용주 공동 신청과 유효한 결정이 필요할 수 있습니다. 계산기는 이런 요건이나 기간 비례 상한을 검사하지 않습니다."],
  },
  en: {
    salary: ["Enter annual or monthly gross pay and any separate contribution assumption. For 2026 taxpayers below AOW age, Box 1 band 1 includes national insurance; this model does not adjust for age or tax credits.", "Annual modeled tax=35.75% through €38,883 + 37.56% through €78,426 + 49.5% above (2026, below AOW age). Estimated net=gross−tax−entered contributions.", "At €50,000 annual pay and 0% separate contributions, modeled tax is €18,076.22 and estimated net is €31,923.78/year (€2,660.32/month), before tax credits.", "Will this match my payslip?", "No. Age/AOW bands, tax credits, payroll items and personal circumstances are not modeled. A 0% separate contribution input does not mean no real-world contributions are due."],
    vat: ["Enter a net amount or gross total, choose the direction, and supply the BTW rate for the transaction. You must classify the supply, exemptions, reverse charge and territory separately.", "VAT on net=net×entered rate/100; gross=net+VAT. For a VAT-inclusive amount, net=total/(1+entered rate/100).", "€1,000 net at entered 21% gives €210 BTW and €1,210 total. Extracting 21% from €1,210 returns €1,000 net.", "Is every Dutch transaction charged at 21%?", "No. The general rate is 21%; specified goods/services use 9%, some cross-border cases use 0%, and some supplies are exempt. This tool does not decide eligibility."],
    ruling: ["Enter annual salary and a scenario percentage. This is percentage arithmetic, not an eligibility decision; the configured 2026 full-year allowance cap is €78,600.", "Potential allowance=min(annual salary×entered rate/100, €78,600); remaining salary=salary−allowance. The engine assumes a full-year period.", "At €80,000 and an entered 30%, the modeled allowance is €24,000 and the remainder is €56,000. This does not confirm approval or eligibility.", "Does this calculator establish eligibility for the 30% facility?", "No. The usual 2026 salary norm is over €48,013, with a lower norm for some under-30 master's graduates and exceptions for qualifying researchers. Recruitment, residence-history, joint employer application and a valid decision also matter; the calculator does not test these or prorate a part year."],
  },
  ja: {
    salary: ["年収または月給と、別枠の拠出率の仮定を入力します。2026年にAOW年齢未満のBox 1第1区分には国民保険料が含まれますが、本モデルは年齢や税額控除を調整しません。", "年税額=€38,883まで35.75%＋€78,426まで次の部分37.56%＋超過分49.5%（2026年、AOW年齢未満）。推定手取り=給与−税−入力拠出額。", "年収€50,000、別拠出率0%では税額€18,076.22、推定手取り€31,923.78/年（€2,660.32/月）です。税額控除前の例です。", "給与明細と同じ結果になりますか？", "いいえ。年齢/AOW区分、税額控除、給与項目や個別事情はモデル化されません。別拠出率0%は実際の負担がないという意味ではありません。"],
    vat: ["税抜額または税込合計を入力し、計算方向と取引に適用するBTW率を選びます。商品区分、免税、リバースチャージ、地域は別途確認してください。", "税抜BTW=税抜額×入力率/100、税込合計=税抜額+BTW。税込入力では税抜額=合計/(1+入力率/100)。", "税抜€1,000に入力率21%ならBTW €210、合計€1,210です。税込€1,210から21%を抽出すると税抜€1,000です。", "オランダの取引はすべて21%ですか？", "いいえ。一般税率は21%、指定品目は9%、一部の国際取引は0%、免税取引もあります。本ツールは適用対象を判定しません。"],
    ruling: ["年収とシナリオ率を入力します。結果は割合の計算で、適格性の判定ではありません。設定された2026年通年上限は€78,600です。", "想定手当=min(年収×入力率/100, €78,600)、残余給与=年収−手当。エンジンは通年を仮定します。", "年収€80,000に30%を入力すると、想定手当€24,000、残余給与€56,000です。承認や適格性を示すものではありません。", "入力するだけで30% facilityの資格が確認できますか？", "いいえ。通常の2026年給与基準は€48,013超で、30歳未満の修士号保有者などは別基準となる場合があります。国外採用、居住歴、雇用主との共同申請と有効な決定も関係し、適格性や途中年の按分は計算しません。"],
  },
  zh: {
    salary: ["输入年薪或月薪及单独假设的缴费率。2026年未到AOW年龄者的Box 1第一档含国民保险费；本模型不按年龄或税收抵免调整。", "年度估算税额=€38,883内按35.75%＋至€78,426部分按37.56%＋超出部分按49.5%（2026年、未到AOW年龄）。估算净薪=工资−税额−输入缴费。", "年薪€50,000、另行缴费率0%时，估算税额€18,076.22，净额€31,923.78/年（€2,660.32/月）；未计税收抵免。", "结果会与工资单一致吗？", "不会。年龄/AOW档、税收抵免、工资项目和个人情况未建模。单独缴费输入0%不代表现实中没有应缴费用。"],
    vat: ["输入未税金额或含税总额，选择计算方向并填写交易适用的BTW税率。商品分类、免税、反向征收和地域适用需另行确认。", "未税BTW=未税金额×输入税率/100；含税总额=未税金额+BTW。含税输入时，未税金额=总额/(1+输入税率/100)。", "未税€1,000按输入21%计算，BTW为€210，总额€1,210。从含税€1,210按21%提取可得未税€1,000。", "荷兰所有交易都按21%吗？", "不是。一般税率21%，指定商品或服务为9%，部分跨境情形为0%，另有免税项目。本工具不判断资格。"],
    ruling: ["输入年薪和情景比例。结果只是比例算术，不判断资格；配置的2026全年免税补贴上限为€78,600。", "潜在补贴=min(年薪×输入率/100, €78,600)；剩余工资=年薪−补贴。引擎按全年处理。", "年薪€80,000、输入30%时，模型补贴€24,000，剩余工资€56,000；这不表示已获批准或符合资格。", "输入后即可确认30% facility资格吗？", "不可以。一般2026工资门槛为超过€48,013，部分未满30岁硕士毕业生适用较低门槛，合格研究人员可能例外。海外招聘、居住记录、雇主共同申请和有效决定也会影响资格；模型不核验这些条件或按年中期间折算。"],
  },
  es: {
    salary: ["Introduce el salario bruto anual o mensual y, si procede, una tasa de cotización aparte. En 2026, el primer tramo de Box 1 para menores de la edad AOW incluye primas nacionales; el modelo no ajusta por edad ni créditos fiscales.", "Impuesto anual modelado=35,75% hasta €38.883 + 37,56% hasta €78.426 + 49,5% sobre el exceso (2026, antes de AOW). Neto estimado=bruto−impuesto−cotización introducida.", "Con €50.000 anuales y 0% de cotización adicional: impuesto €18.076,22 y neto estimado €31.923,78/año (€2.660,32/mes), antes de créditos fiscales.", "¿Coincidirá con mi nómina?", "No. Edad/tramos AOW, créditos fiscales, conceptos de nómina y circunstancias personales no se modelan. Una cotización aparte del 0% no significa que no existan cargas reales."],
    vat: ["Introduce una base o un total, elige el sentido y señala el tipo BTW de la operación. Clasificación del bien, exenciones, inversión del sujeto pasivo y territorio deben verificarse aparte.", "BTW sobre base=base×tipo introducido/100; total=base+BTW. Si el importe incluye impuesto, base=total/(1+tipo introducido/100).", "Una base de €1.000 al 21% introducido genera €210 BTW y €1.210 en total. Al extraer el 21% de €1.210 se obtienen €1.000 de base.", "¿Todas las operaciones neerlandesas llevan el 21%?", "No. El general es 21%; ciertos bienes o servicios tributan al 9%, algunos casos transfronterizos al 0% y también hay exenciones. La herramienta no decide qué supuesto corresponde."],
    ruling: ["Introduce el salario anual y un porcentaje para el escenario. Es una operación matemática, no una decisión de elegibilidad; el límite anual completo configurado para 2026 es €78.600.", "Asignación potencial=min(salario anual×tipo introducido/100, €78.600); salario restante=salario−asignación. El motor supone el año completo.", "Con €80.000 y un 30% introducido, la asignación modelada es €24.000 y quedan €56.000. No confirma aprobación ni elegibilidad.", "¿El resultado confirma que cumplo el régimen del 30%?", "No. El umbral salarial general de 2026 supera €48.013; algunos titulados menores de 30 años y ciertos investigadores tienen reglas distintas. También importan contratación desde el extranjero, residencia previa, solicitud conjunta del empleador y una resolución válida. La calculadora no verifica esos requisitos ni prorratea un año parcial."],
  },
  "pt-br": {
    salary: ["Informe o salário bruto anual ou mensal e uma hipótese separada de contribuição. Em 2026, a primeira faixa Box 1 para quem ainda não atingiu a idade AOW inclui contribuições nacionais; o modelo não ajusta por idade nem créditos fiscais.", "Imposto anual modelado=35,75% até €38.883 + 37,56% até €78.426 + 49,5% no excedente (2026, antes da idade AOW). Líquido estimado=bruto−imposto−contribuição informada.", "Com €50.000 anuais e 0% de contribuição adicional: imposto €18.076,22 e líquido estimado €31.923,78/ano (€2.660,32/mês), antes de créditos fiscais.", "O resultado será igual ao holerite?", "Não. Idade/faixas AOW, créditos fiscais, itens da folha e circunstâncias pessoais não são modelados. Informar 0% de contribuição separada não significa ausência de encargos reais."],
    vat: ["Informe o valor líquido ou total, escolha o sentido e indique a taxa BTW aplicável à operação. Classificação do produto, isenção, autoliquidação e território devem ser verificados à parte.", "BTW sobre líquido=líquido×taxa informada/100; total=líquido+BTW. Para valor com imposto, líquido=total/(1+taxa informada/100).", "€1.000 líquidos a 21% informado geram €210 de BTW e €1.210 no total. Extraindo 21% de €1.210, o líquido volta a €1.000.", "Todas as operações neerlandesas usam 21%?", "Não. O padrão é 21%; certos bens/serviços usam 9%, algumas operações internacionais usam 0% e há isenções. A ferramenta não classifica a operação."],
    ruling: ["Informe o salário anual e uma porcentagem de cenário. É uma conta proporcional, não uma decisão de elegibilidade; o limite anual integral configurado para 2026 é €78.600.", "Benefício potencial=min(salário anual×taxa informada/100, €78.600); salário restante=salário−benefício. O motor pressupõe o ano completo.", "Com €80.000 e 30% informado, o benefício modelado é €24.000 e restam €56.000. Isso não confirma aprovação ou elegibilidade.", "O resultado confirma que tenho direito ao regime de 30%?", "Não. O limite salarial geral de 2026 é superior a €48.013, com faixa menor para alguns mestres abaixo de 30 anos e exceção para pesquisadores elegíveis. Recrutamento no exterior, histórico de residência, pedido conjunto e decisão válida também importam; o cálculo não verifica esses requisitos nem proporcionaliza ano parcial."],
  },
  de: {
    salary: ["Jahres- oder Monatsbrutto und gegebenenfalls einen separaten Beitragsansatz eingeben. 2026 enthält die erste Box-1-Stufe für Personen unter dem AOW-Alter Sozialversicherungsbeiträge; Alter und Steuergutschriften werden nicht berücksichtigt.", "Modellsteuer pro Jahr=35,75% bis €38.883 + 37,56% bis €78.426 + 49,5% darüber (2026, unter AOW-Alter). Geschätztes Netto=Brutto−Steuer−eingegebener Beitrag.", "Bei €50.000 Jahresbrutto und 0% Zusatzbeitrag: Modellsteuer €18.076,22 und geschätztes Netto €31.923,78/Jahr (€2.660,32/Monat), vor Steuergutschriften.", "Entspricht das meiner Gehaltsabrechnung?", "Nein. Alter/AOW-Stufen, Steuergutschriften, einzelne Lohnbestandteile und persönliche Umstände fehlen. 0% beim separaten Beitrag bedeutet nicht, dass real keine Beiträge fällig sind."],
    vat: ["Nettobetrag oder Bruttosumme eingeben, Richtung wählen und den BTW-Satz für den Umsatz einsetzen. Warenart, Befreiung, Reverse-Charge und Gebiet müssen separat geprüft werden.", "BTW auf netto=netto×eingegebener Satz/100; brutto=netto+BTW. Bei Bruttopreis=gesamt/(1+eingegebener Satz/100).", "€1.000 netto mit eingegebenen 21% ergeben €210 BTW und €1.210 brutto. Bei Extraktion aus €1.210 bleiben €1.000 netto.", "Gelten 21% für jeden Umsatz in den Niederlanden?", "Nein. Der allgemeine Satz beträgt 21%; bestimmte Waren/Dienstleistungen haben 9%, manche grenzüberschreitenden Fälle 0%, daneben gibt es Befreiungen. Das Tool prüft die Einordnung nicht."],
    ruling: ["Jahresgehalt und einen Szenarioprozentsatz eingeben. Das Ergebnis ist keine Berechtigungsprüfung; die konfigurierte volle Jahresobergrenze 2026 beträgt €78.600.", "Mögliche steuerfreie Zulage=min(Jahresgehalt×eingegebener Satz/100, €78.600); Restgehalt=Gehalt−Zulage. Die Engine nimmt ein volles Jahr an.", "Bei €80.000 und eingegebenen 30% beträgt die modellierte Zulage €24.000, der Rest €56.000. Das bestätigt keine Genehmigung.", "Bestätigt der Rechner meinen Anspruch auf die 30%-Regelung?", "Nein. Die allgemeine Gehaltsnorm 2026 liegt über €48.013; für manche Masterabsolventen unter 30 gilt eine niedrigere Norm, qualifizierte Forschende können ausgenommen sein. Einstellung aus dem Ausland, Wohnsitzhistorie, gemeinsamer Antrag und gültiger Bescheid sind ebenfalls relevant; der Rechner prüft oder anteilt diese Bedingungen nicht."],
  },
  fr: {
    salary: ["Saisissez le brut annuel ou mensuel et, si besoin, une hypothèse de cotisation séparée. En 2026, la première tranche Box 1 sous l’âge AOW inclut les assurances nationales; le modèle n’ajuste ni l’âge ni les crédits d’impôt.", "Impôt annuel modélisé=35,75% jusqu’à €38 883 + 37,56% jusqu’à €78 426 + 49,5% au-delà (2026, avant AOW). Net estimé=brut−impôt−cotisation saisie.", "Avec €50 000/an et 0% de cotisation séparée: impôt €18 076,22 et net estimé €31 923,78/an (€2 660,32/mois), avant crédits d’impôt.", "Le résultat sera-t-il celui de ma fiche de paie ?", "Non. Âge/tranches AOW, crédits d’impôt, éléments de paie et situation personnelle ne sont pas modélisés. Une cotisation séparée à 0% ne signifie pas qu’aucune cotisation réelle n’est due."],
    vat: ["Saisissez une base HT ou un total TTC, choisissez le sens du calcul et indiquez le taux BTW de l’opération. Produit, exonération, autoliquidation et territoire sont à vérifier séparément.", "BTW sur HT=HT×taux saisi/100; TTC=HT+BTW. Pour un montant TTC, HT=total/(1+taux saisi/100).", "€1 000 HT avec 21% saisi donnent €210 de BTW et €1 210 TTC. En extrayant 21% de €1 210, on retrouve €1 000 HT.", "Toutes les opérations néerlandaises sont-elles à 21% ?", "Non. Le taux général est 21%; certains biens/services relèvent de 9%, certains cas transfrontaliers de 0% et il existe des exonérations. L’outil ne classe pas l’opération."],
    ruling: ["Saisissez le salaire annuel et un pourcentage de scénario. Le résultat est arithmétique, sans décision d’éligibilité; le plafond annuel complet configuré pour 2026 est €78 600.", "Allocation potentielle=min(salaire annuel×taux saisi/100, €78 600); solde salarial=salaire−allocation. Le moteur suppose une année complète.", "À €80 000 avec 30% saisi, l’allocation modélisée est €24 000 et le solde €56 000. Cela ne confirme ni accord ni éligibilité.", "Le calcul confirme-t-il mon droit au régime de 30% ?", "Non. Le seuil salarial général 2026 dépasse €48 013; un seuil inférieur s’applique à certains diplômés de master de moins de 30 ans et des chercheurs peuvent être exemptés. Recrutement depuis l’étranger, résidence antérieure, demande conjointe et décision valide comptent aussi; l’outil ne les vérifie pas et ne prorata pas une année partielle."],
  },
  vi: {
    salary: ["Nhập lương gộp năm hoặc tháng và giả định riêng về khoản đóng góp. Năm 2026, bậc Box 1 đầu tiên của người chưa đến tuổi AOW đã gồm bảo hiểm quốc gia; mô hình không điều chỉnh theo tuổi hay tín dụng thuế.", "Thuế năm mô hình=35,75% đến €38.883 + 37,56% đến €78.426 + 49,5% phần vượt (2026, dưới tuổi AOW). Thực nhận ước tính=gộp−thuế−khoản đóng đã nhập.", "Lương năm €50.000, khoản đóng riêng 0%: thuế mô hình €18.076,22; thực nhận ước tính €31.923,78/năm (€2.660,32/tháng), chưa tính tín dụng thuế.", "Kết quả có giống phiếu lương không?", "Không. Tuổi/bậc AOW, tín dụng thuế, từng khoản lương và hoàn cảnh cá nhân chưa được mô hình hóa. Nhập 0% khoản đóng riêng không có nghĩa là thực tế không phải đóng."],
    vat: ["Nhập giá chưa thuế hoặc tổng đã thuế, chọn chiều tính và nhập mức BTW của giao dịch. Cần tự xác định loại hàng, miễn thuế, cơ chế đảo ngược và lãnh thổ.", "BTW trên giá ròng=giá ròng×tỷ lệ nhập/100; tổng=gốc+BTW. Với tổng đã thuế, giá ròng=tổng/(1+tỷ lệ nhập/100).", "Giá ròng €1.000 với mức nhập 21% cho BTW €210 và tổng €1.210. Tách 21% từ €1.210 thu được giá ròng €1.000.", "Mọi giao dịch ở Hà Lan đều chịu 21%?", "Không. Mức chung là 21%; một số hàng/dịch vụ dùng 9%, một số giao dịch xuyên biên giới 0% và có trường hợp miễn thuế. Công cụ không phân loại giao dịch."],
    ruling: ["Nhập lương năm và tỷ lệ cho tình huống giả định. Đây là phép tính tỷ lệ, không phải quyết định đủ điều kiện; mức trần cả năm 2026 được cấu hình là €78.600.", "Khoản miễn thuế tiềm năng=min(lương năm×tỷ lệ nhập/100, €78.600); phần lương còn lại=lương−khoản này. Engine giả định đủ năm.", "Lương €80.000 với tỷ lệ nhập 30% cho khoản mô hình €24.000 và phần còn lại €56.000. Kết quả không xác nhận phê duyệt hay đủ điều kiện.", "Nhập số liệu có xác nhận được quyền dùng chế độ 30% không?", "Không. Ngưỡng lương chung năm 2026 là trên €48.013; một số người có bằng thạc sĩ dưới 30 tuổi có ngưỡng thấp hơn, nghiên cứu viên đủ điều kiện có thể được miễn. Tuyển từ nước ngoài, lịch sử cư trú, hồ sơ chung với chủ lao động và quyết định còn hiệu lực cũng quan trọng; công cụ không kiểm tra hoặc chia tỷ lệ năm lẻ."],
  },
  id: {
    salary: ["Masukkan gaji bruto tahunan atau bulanan dan asumsi iuran terpisah bila ada. Pada 2026, lapisan pertama Box 1 bagi orang di bawah usia AOW mencakup premi asuransi nasional; model tidak menyesuaikan usia atau kredit pajak.", "Pajak tahunan model=35,75% sampai €38.883 + 37,56% sampai €78.426 + 49,5% di atasnya (2026, sebelum usia AOW). Bersih estimasi=bruto−pajak−iuran yang dimasukkan.", "Gaji €50.000/tahun dan iuran terpisah 0% menghasilkan pajak model €18.076,22 serta bersih €31.923,78/tahun (€2.660,32/bulan), sebelum kredit pajak.", "Apakah hasilnya sama dengan slip gaji?", "Tidak. Usia/lapisan AOW, kredit pajak, komponen payroll, dan keadaan pribadi tidak dimodelkan. Iuran terpisah 0% bukan berarti tidak ada iuran yang wajib dibayar."],
    vat: ["Masukkan nilai sebelum pajak atau total, pilih arah hitung, lalu isi tarif BTW transaksi. Kategori barang, pembebasan, reverse charge, dan wilayah harus diperiksa sendiri.", "BTW atas nilai neto=neto×tarif masukan/100; total=neto+BTW. Untuk total termasuk pajak, neto=total/(1+tarif masukan/100).", "Neto €1.000 pada 21% yang dimasukkan menghasilkan BTW €210 dan total €1.210. Mengekstrak 21% dari €1.210 mengembalikan neto €1.000.", "Apakah semua transaksi Belanda memakai 21%?", "Tidak. Tarif umum 21%; barang/jasa tertentu 9%, sebagian transaksi lintas batas 0%, dan ada pembebasan. Alat tidak menentukan klasifikasi transaksi."],
    ruling: ["Masukkan gaji tahunan dan persentase skenario. Ini hitungan matematika, bukan keputusan kelayakan; batas tahunan penuh 2026 yang dikonfigurasi €78.600.", "Tunjangan potensial=min(gaji tahunan×tarif masukan/100, €78.600); sisa gaji=gaji−tunjangan. Mesin mengasumsikan satu tahun penuh.", "Dengan gaji €80.000 dan 30% masukan, tunjangan model €24.000 dan sisanya €56.000. Ini tidak membuktikan persetujuan atau kelayakan.", "Apakah hasil ini memastikan kelayakan fasilitas 30%?", "Tidak. Ambang gaji umum 2026 lebih dari €48.013; beberapa lulusan master di bawah 30 tahun memiliki ambang lebih rendah dan peneliti yang memenuhi syarat dapat dikecualikan. Perekrutan dari luar negeri, riwayat tinggal, permohonan bersama pemberi kerja, dan keputusan valid juga penting; alat tidak memeriksa syarat atau memprorata tahun parsial."],
  },
  th: {
    salary: ["กรอกเงินเดือนรวมรายปีหรือรายเดือนและสมมติฐานเงินสมทบแยกต่างหาก หากมี ในปี 2026 ขั้นแรก Box 1 สำหรับผู้ที่ยังไม่ถึงอายุ AOW รวมเงินประกันสังคมแล้ว โมเดลไม่ปรับตามอายุหรือเครดิตภาษี", "ภาษีรายปีตามโมเดล=35.75% ถึง €38,883 + 37.56% ถึง €78,426 + 49.5% ส่วนเกิน (2026 ก่อนอายุ AOW) เงินสุทธิประมาณ=เงินเดือนรวม−ภาษี−เงินสมทบที่กรอก", "เงินเดือน €50,000/ปี และเงินสมทบแยก 0% ให้ภาษีโมเดล €18,076.22 และสุทธิประมาณ €31,923.78/ปี (€2,660.32/เดือน) ก่อนเครดิตภาษี", "ผลจะตรงกับสลิปเงินเดือนหรือไม่?", "ไม่ โมเดลไม่รวมอายุ/ขั้น AOW เครดิตภาษี รายการค่าจ้างและสถานการณ์ส่วนบุคคล การกรอกเงินสมทบแยก 0% ไม่ได้แปลว่าไม่มีภาระจริง"],
    vat: ["กรอกยอดก่อนภาษีหรือยอดรวม เลือกทิศทางและระบุอัตรา BTW ของธุรกรรม ต้องตรวจประเภทสินค้า การยกเว้น reverse charge และพื้นที่ด้วยตนเอง", "BTW บนยอดสุทธิ=ยอดสุทธิ×อัตราที่กรอก/100; ยอดรวม=ยอดสุทธิ+BTW หากยอดรวมภาษีแล้ว ยอดสุทธิ=ยอดรวม/(1+อัตราที่กรอก/100)", "ยอดสุทธิ €1,000 ที่อัตรากรอก 21% ได้ BTW €210 รวม €1,210 แยก 21% จาก €1,210 จะได้ยอดสุทธิ €1,000", "ธุรกรรมในเนเธอร์แลนด์ทั้งหมดใช้อัตรา 21% หรือไม่?", "ไม่ อัตราทั่วไป 21%; สินค้าหรือบริการบางชนิด 9%, บางกรณีข้ามพรมแดน 0% และมีรายการยกเว้น เครื่องมือไม่จัดประเภทธุรกรรม"],
    ruling: ["กรอกเงินเดือนรายปีและเปอร์เซ็นต์สำหรับสถานการณ์สมมติ นี่คือการคำนวณตามสัดส่วน ไม่ใช่การตัดสินสิทธิ; เพดานเต็มปี 2026 ที่ตั้งไว้คือ €78,600", "เงินชดเชยปลอดภาษีที่อาจได้=min(เงินเดือน×อัตราที่กรอก/100, €78,600); เงินเดือนส่วนที่เหลือ=เงินเดือน−เงินชดเชย เครื่องคำนวณสมมติครบปี", "เงินเดือน €80,000 และกรอก 30% ให้เงินชดเชยโมเดล €24,000 เหลือ €56,000 ไม่ยืนยันการอนุมัติหรือสิทธิ", "ผลคำนวณยืนยันสิทธิ 30% facility หรือไม่?", "ไม่ เกณฑ์เงินเดือนทั่วไปปี 2026 มากกว่า €48,013; ผู้จบปริญญาโทบางรายอายุต่ำกว่า 30 ปีมีเกณฑ์ต่ำกว่า และนักวิจัยที่เข้าเกณฑ์อาจได้รับยกเว้น การรับเข้าทำงานจากต่างประเทศ ประวัติถิ่นที่อยู่ การยื่นร่วมกับนายจ้าง และคำสั่งที่ยังมีผลก็สำคัญ เครื่องมือไม่ตรวจเงื่อนไขหรือเฉลี่ยปีที่ไม่ครบ"],
  },
  "zh-tw": {
    salary: ["輸入年薪或月薪及另行假設的提繳率。2026年未達AOW年齡者的Box 1第一級已包含國民保險費；模型不按年齡或稅額抵減調整。", "年度模型稅額=€38,883內35.75%＋至€78,426部分37.56%＋超額部分49.5%（2026、未達AOW年齡）。估算淨額=薪資−稅−輸入提繳。", "年薪€50,000、另行提繳率0%時，模型稅額€18,076.22，估算淨額€31,923.78/年（€2,660.32/月），未計稅額抵減。", "結果會與薪資單一致嗎？", "不會。年齡/AOW級距、稅額抵減、薪資項目及個人狀況未納入。另行提繳輸入0%不代表實際沒有應繳款項。"],
    vat: ["輸入未稅金額或含稅總額，選擇方向並填入交易適用的BTW稅率。商品分類、免稅、反向課稅與地區需另行確認。", "未稅BTW=未稅金額×輸入率/100；含稅總額=未稅金額+BTW。含稅輸入時，未稅金額=總額/(1+輸入率/100)。", "未稅€1,000以輸入21%計算，BTW為€210，總額€1,210。從含稅€1,210按21%拆出可得未稅€1,000。", "荷蘭所有交易都用21%嗎？", "不是。一般稅率21%，指定商品或服務為9%，部分跨境情形為0%，另有免稅項目。本工具不判定適用資格。"],
    ruling: ["輸入年薪及情境百分比。這是比例計算，不是資格判定；設定的2026全年上限為€78,600。", "可能免稅補貼=min(年薪×輸入率/100, €78,600)；剩餘薪資=年薪−補貼。引擎假設完整年度。", "年薪€80,000、輸入30%時，模型補貼€24,000，剩餘€56,000；這不表示已核准或符合資格。", "輸入資料能確認30% facility資格嗎？", "不能。2026一般薪資門檻為超過€48,013，部分未滿30歲碩士畢業生另有較低門檻，符合條件的研究人員可能例外。海外招募、居住紀錄、雇主共同申請與有效核准也很重要；計算器不檢查條件或按部分年度比例折算。"],
  },
  it: {
    salary: ["Inserisci il lordo annuo o mensile e un’eventuale ipotesi separata di contributi. Nel 2026 la prima fascia Box 1 sotto l’età AOW comprende i premi nazionali; il modello non adegua per età o crediti d’imposta.", "Imposta annua modellata=35,75% fino a €38.883 + 37,56% fino a €78.426 + 49,5% sull’eccedenza (2026, prima dell’età AOW). Netto stimato=lordo−imposta−contributi inseriti.", "Con €50.000 annui e contributi separati allo 0%: imposta €18.076,22 e netto stimato €31.923,78/anno (€2.660,32/mese), prima dei crediti.", "Il risultato coincide con la busta paga?", "No. Età/fasce AOW, crediti, voci di busta paga e condizioni personali non sono modellati. Un contributo separato allo 0% non significa che non siano dovuti contributi reali."],
    vat: ["Inserisci imponibile o totale, scegli la direzione e indica l’aliquota BTW della transazione. Categoria, esenzioni, reverse charge e territorio vanno verificati a parte.", "BTW sull’imponibile=imponibile×aliquota inserita/100; totale=imponibile+BTW. Se il totale include l’imposta, imponibile=totale/(1+aliquota inserita/100).", "€1.000 imponibili al 21% inserito producono €210 di BTW e €1.210 totali. Estraendo il 21% da €1.210 si ottengono €1.000 imponibili.", "Tutte le operazioni olandesi sono al 21%?", "No. L’aliquota generale è 21%; alcuni beni/servizi usano il 9%, certi casi transfrontalieri lo 0% e alcune operazioni sono esenti. Lo strumento non classifica l’operazione."],
    ruling: ["Inserisci salario annuo e percentuale dello scenario. È un calcolo proporzionale, non una verifica di idoneità; il limite intero annuo configurato per il 2026 è €78.600.", "Indennità potenziale=min(salario annuo×aliquota inserita/100, €78.600); salario residuo=salario−indennità. Il motore presume l’anno intero.", "Con €80.000 e 30% inserito, l’indennità modellata è €24.000 e il residuo €56.000. Non conferma approvazione o idoneità.", "Il risultato conferma il diritto al regime del 30%?", "No. La soglia salariale generale 2026 supera €48.013; alcuni laureati magistrali sotto i 30 anni hanno una soglia inferiore e ricercatori idonei possono essere esentati. Contano anche assunzione dall’estero, residenza precedente, domanda congiunta e decisione valida; lo strumento non verifica tali condizioni né riproporziona l’anno parziale."],
  },
  nl: {
    salary: ["Vul jaar- of maandbruto in en eventueel een aparte aangenomen bijdrage. In 2026 bevat de eerste Box 1-schijf voor mensen onder de AOW-leeftijd volksverzekeringspremies; leeftijd en heffingskortingen worden niet aangepast.", "Berekende jaarbelasting=35,75% tot €38.883 + 37,56% tot €78.426 + 49,5% daarboven (2026, onder AOW-leeftijd). Geschat netto=bruto−belasting−ingevoerde bijdrage.", "Bij €50.000 jaarloon en 0% aparte bijdrage: modelbelasting €18.076,22 en geschat netto €31.923,78/jaar (€2.660,32/maand), vóór heffingskortingen.", "Is dit gelijk aan mijn loonstrook?", "Nee. Leeftijd/AOW-schijven, heffingskortingen, looncomponenten en persoonlijke omstandigheden ontbreken. Een aparte bijdrage van 0% betekent niet dat er werkelijk geen bijdragen verschuldigd zijn."],
    vat: ["Vul een bedrag exclusief of inclusief BTW in, kies de richting en geef het BTW-tarief voor de transactie op. Productsoort, vrijstelling, verlegging en gebied moet u apart bepalen.", "BTW over netto=netto×ingevoerd tarief/100; bruto=netto+BTW. Bij een bedrag inclusief BTW is netto=totaal/(1+ingevoerd tarief/100).", "€1.000 exclusief BTW bij ingevoerde 21% geeft €210 BTW en €1.210 totaal. Bij extractie uit €1.210 blijft €1.000 netto over.", "Geldt 21% voor iedere Nederlandse transactie?", "Nee. Het algemene tarief is 21%; bepaalde goederen/diensten vallen onder 9%, sommige grensoverschrijdende gevallen onder 0% en er zijn vrijstellingen. De tool bepaalt de categorie niet."],
    ruling: ["Vul het jaarloon en een scenario-percentage in. Dit is een rekensom, geen toets van uw recht; de ingestelde volledige jaargrens voor 2026 is €78.600.", "Mogelijke onbelaste vergoeding=min(jaarloon×ingevoerd percentage/100, €78.600); resterend loon=loon−vergoeding. De engine gaat uit van een volledig jaar.", "Bij €80.000 en ingevoerde 30% is de modelvergoeding €24.000 en resteert €56.000. Dit bevestigt geen beschikking of recht.", "Bewijst de uitkomst dat ik recht heb op de 30%-regeling?", "Nee. De algemene salarisnorm voor 2026 is meer dan €48.013; sommige masters onder 30 hebben een lagere norm en kwalificerende onderzoekers kunnen zijn uitgezonderd. Werving uit het buitenland, woonhistorie, gezamenlijke aanvraag en geldige beschikking zijn ook van belang; dit model toetst dit niet en rekent een deeljaar niet naar rato."],
  },
  hi: {
    salary: ["वार्षिक या मासिक सकल वेतन और अलग अनुमानित योगदान दर दें। 2026 में AOW आयु से कम लोगों की पहली Box 1 दर में राष्ट्रीय बीमा प्रीमियम शामिल हैं; मॉडल उम्र और टैक्स क्रेडिट के अनुसार समायोजन नहीं करता।", "मॉडल वार्षिक कर=€38,883 तक 35.75% + €78,426 तक 37.56% + उससे ऊपर 49.5% (2026, AOW आयु से कम)। अनुमानित नेट=सकल−कर−दर्ज योगदान।", "€50,000 वार्षिक वेतन और अलग योगदान 0% पर मॉडल कर €18,076.22 तथा अनुमानित नेट €31,923.78/वर्ष (€2,660.32/माह) है; टैक्स क्रेडिट से पहले।", "क्या यह वेतन पर्ची के समान होगा?", "नहीं। आयु/AOW दर, टैक्स क्रेडिट, वेतन मदें और व्यक्तिगत हालात शामिल नहीं हैं। अलग योगदान 0% देने का मतलब वास्तविक देय योगदान शून्य नहीं है।"],
    vat: ["कर-पूर्व राशि या कुल राशि दें, गणना दिशा चुनें और लेनदेन की BTW दर भरें। वस्तु वर्ग, छूट, रिवर्स चार्ज और क्षेत्र अलग से जाँचें।", "शुद्ध पर BTW=शुद्ध×दर्ज दर/100; कुल=शुद्ध+BTW। कर सहित राशि में शुद्ध=कुल/(1+दर्ज दर/100)।", "€1,000 शुद्ध पर दर्ज 21% से €210 BTW और €1,210 कुल बनते हैं। €1,210 से 21% निकालने पर शुद्ध €1,000 मिलता है।", "क्या हर डच लेनदेन पर 21% लगता है?", "नहीं। सामान्य दर 21%; कुछ वस्तु/सेवाएँ 9%, कुछ सीमा-पार स्थितियाँ 0% और कुछ छूट के अंतर्गत हैं। टूल पात्रता तय नहीं करता।"],
    ruling: ["वार्षिक वेतन और परिदृश्य प्रतिशत दें। यह अनुपात गणना है, पात्रता निर्णय नहीं; 2026 के लिए कॉन्फ़िगर पूरे-वर्ष की सीमा €78,600 है।", "संभावित भत्ता=min(वार्षिक वेतन×दर्ज दर/100, €78,600); शेष वेतन=वेतन−भत्ता। इंजन पूरे वर्ष की धारणा लेता है।", "€80,000 वेतन और दर्ज 30% पर मॉडल भत्ता €24,000 और शेष वेतन €56,000 है। यह मंज़ूरी या पात्रता सिद्ध नहीं करता।", "क्या परिणाम 30% facility की पात्रता की पुष्टि करता है?", "नहीं। 2026 सामान्य वेतन सीमा €48,013 से अधिक है; 30 से कम आयु के कुछ मास्टर स्नातकों के लिए कम सीमा और योग्य शोधकर्ताओं के लिए अपवाद हो सकता है। विदेश से भर्ती, निवास इतिहास, नियोक्ता के साथ संयुक्त आवेदन और वैध निर्णय भी आवश्यक हो सकते हैं; टूल शर्तें नहीं जाँचता और आंशिक वर्ष का अनुपात नहीं करता।"],
  },
  ru: {
    salary: ["Введите годовую или месячную зарплату брутто и, при необходимости, отдельную предполагаемую ставку взносов. В первой ставке Box 1 за 2026 год для лиц младше возраста AOW учтены национальные страховые взносы; возраст и налоговые льготы не корректируются.", "Расчетный годовой налог=35,75% до €38 883 + 37,56% до €78 426 + 49,5% сверх суммы (2026, до возраста AOW). Оценка нетто=брутто−налог−введенные взносы.", "При €50 000 в год и отдельных взносах 0% модельный налог €18 076,22, оценка нетто €31 923,78/год (€2 660,32/мес.), до налоговых льгот.", "Совпадет ли расчет с расчетным листком?", "Нет. Возраст/ставки AOW, налоговые льготы, компоненты зарплаты и личные обстоятельства не учтены. Отдельная ставка 0% не означает отсутствие реальных обязательных взносов."],
    vat: ["Введите сумму без BTW или итог, выберите направление и укажите ставку BTW для операции. Категорию товара, освобождение, обратное начисление и территорию проверьте отдельно.", "BTW на нетто=нетто×введенная ставка/100; итого=нетто+BTW. Для суммы с налогом нетто=итого/(1+введенная ставка/100).", "€1 000 без BTW при введенных 21% дают €210 BTW и €1 210 итого. Из €1 210 можно выделить €1 000 без налога.", "Для всех операций в Нидерландах действует 21%?", "Нет. Общая ставка 21%; для отдельных товаров/услуг — 9%, в некоторых трансграничных случаях — 0%, также есть освобождения. Инструмент не определяет категорию."],
    ruling: ["Введите годовую зарплату и процент сценария. Это арифметика, а не проверка права; установленный предел на полный 2026 год — €78 600.", "Возможное освобождаемое пособие=min(годовая зарплата×введенный процент/100, €78 600); остаток зарплаты=зарплата−пособие. Модель предполагает полный год.", "При зарплате €80 000 и введенных 30% модельное пособие €24 000, остаток €56 000. Это не подтверждает одобрение или право.", "Подтверждает ли расчет право на режим 30%?", "Нет. Общий зарплатный порог 2026 года выше €48 013; для некоторых магистров младше 30 лет порог ниже, а квалифицированные исследователи могут иметь исключение. Важны также найм из-за границы, история проживания, совместная заявка работодателя и действующее решение; инструмент не проверяет условия и не пересчитывает неполный год пропорционально."],
  },
  tr: {
    salary: ["Yıllık veya aylık brüt ücreti ve varsa ayrı katkı varsayımını girin. 2026'da AOW yaşından küçükler için ilk Box 1 dilimi ulusal sigorta primlerini içerir; model yaşa ve vergi kredilerine göre düzeltme yapmaz.", "Model yıllık vergi=€38.883'e kadar %35,75 + €78.426'ya kadar %37,56 + aşan kısma %49,5 (2026, AOW yaşından önce). Tahmini net=brüt−vergi−girilen katkı.", "Yıllık €50.000 ücret ve ayrı katkı %0 iken model vergisi €18.076,22, tahmini net €31.923,78/yıl (€2.660,32/ay); vergi kredileri hariç.", "Bu sonuç maaş bordromla aynı olur mu?", "Hayır. Yaş/AOW dilimleri, vergi kredileri, bordro kalemleri ve kişisel koşullar modellenmez. Ayrı katkının %0 olması gerçek hayatta katkı borcu olmadığı anlamına gelmez."],
    vat: ["Vergisiz tutarı veya toplamı girin, yönü seçin ve işlem için BTW oranını belirtin. Ürün sınıfı, istisna, reverse charge ve bölgeyi ayrıca doğrulayın.", "Net üzerinden BTW=net×girilen oran/100; toplam=net+BTW. Vergi dahil tutarda net=toplam/(1+girilen oran/100).", "Girilen %21 ile €1.000 net tutar €210 BTW ve €1.210 toplam verir. €1.210 içinden %21 çıkarılınca net €1.000 olur.", "Hollanda'daki her işlemde %21 mi uygulanır?", "Hayır. Genel oran %21; belirli mal/hizmetlerde %9, bazı sınır ötesi işlemlerde %0 ve muafiyetler vardır. Araç işlemi sınıflandırmaz."],
    ruling: ["Yıllık maaşı ve senaryo oranını girin. Bu bir uygunluk kararı değil, oran hesabıdır; yapılandırılmış 2026 tam yıl üst sınırı €78.600'dür.", "Olası vergisiz ödeme=min(yıllık maaş×girilen oran/100, €78.600); kalan maaş=maaş−ödeme. Motor tam yılı varsayar.", "€80.000 maaş ve girilen %30 ile model ödemesi €24.000, kalan maaş €56.000 olur. Bu, onay veya uygunluğu doğrulamaz.", "Sonuç 30% facility hakkımı kanıtlar mı?", "Hayır. 2026 genel maaş eşiği €48.013 üzerindedir; 30 yaş altındaki bazı yüksek lisans mezunları için eşik düşüktür ve nitelikli araştırmacılara istisna olabilir. Yurt dışından işe alım, ikamet geçmişi, işverenle ortak başvuru ve geçerli karar da önemlidir; araç koşulları denetlemez veya kısmi yılı oranlamaz."],
  },
  pl: {
    salary: ["Wpisz roczne lub miesięczne brutto i ewentualne osobne założenie składek. W 2026 r. pierwsza stawka Box 1 dla osób przed wiekiem AOW obejmuje składki ubezpieczeń społecznych; model nie koryguje wieku ani ulg.", "Modelowy podatek roczny=35,75% do €38 883 + 37,56% do €78 426 + 49,5% nadwyżki (2026, przed wiekiem AOW). Szacowane netto=brutto−podatek−wpisane składki.", "Przy €50 000 rocznie i osobnych składkach 0% podatek modelowy to €18 076,22, a netto €31 923,78/rok (€2 660,32/mies.), przed ulgami.", "Czy wynik będzie zgodny z paskiem płac?", "Nie. Wiek/progi AOW, ulgi podatkowe, składniki płacy i sytuacja osobista nie są modelowane. Osobne 0% składek nie oznacza braku rzeczywistych należności."],
    vat: ["Wpisz kwotę netto lub brutto, wybierz kierunek i podaj stawkę BTW transakcji. Rodzaj towaru, zwolnienie, odwrotne obciążenie i terytorium trzeba sprawdzić osobno.", "BTW od netto=netto×wpisana stawka/100; brutto=netto+BTW. Dla kwoty z podatkiem netto=całość/(1+wpisana stawka/100).", "€1 000 netto przy wpisanych 21% daje €210 BTW i €1 210 brutto. Wyodrębnienie 21% z €1 210 zwraca €1 000 netto.", "Czy każda transakcja w Holandii podlega 21%?", "Nie. Stawka ogólna wynosi 21%; wybrane towary/usługi mają 9%, niektóre transgraniczne przypadki 0%, istnieją też zwolnienia. Narzędzie nie klasyfikuje transakcji."],
    ruling: ["Wpisz roczne wynagrodzenie i procent scenariusza. To rachunek procentowy, a nie ocena uprawnienia; skonfigurowany limit za pełny 2026 rok wynosi €78 600.", "Potencjalny dodatek=min(roczna płaca×wpisana stawka/100, €78 600); pozostała płaca=płaca−dodatek. Silnik zakłada pełny rok.", "Przy €80 000 i wpisanych 30% modelowy dodatek wynosi €24 000, a pozostałość €56 000. Nie potwierdza to zgody ani uprawnienia.", "Czy wynik potwierdza prawo do ulgi 30%?", "Nie. Ogólny próg płacowy na 2026 r. przekracza €48 013; niektórzy absolwenci studiów magisterskich poniżej 30 lat mają niższy próg, a kwalifikowani naukowcy mogą być wyłączeni. Liczą się też rekrutacja z zagranicy, historia zamieszkania, wspólny wniosek pracodawcy i ważna decyzja; kalkulator tego nie sprawdza ani nie dzieli roku proporcjonalnie."],
  },
  fil: {
    salary: ["Ilagay ang taunang o buwanang gross pay at hiwalay na palagay na kontribusyon kung mayroon. Sa 2026, kasama sa unang Box 1 band para sa wala pa sa edad AOW ang pambansang insurance premiums; walang age o tax-credit adjustment ang modelo.", "Modelong taunang buwis=35.75% hanggang €38,883 + 37.56% hanggang €78,426 + 49.5% sa lampas (2026, bago edad AOW). Tantiyang net=gross−buwis−ipinasok na kontribusyon.", "Sa €50,000 taunang sahod at 0% hiwalay na kontribusyon: modelong buwis €18,076.22 at tantiyang net €31,923.78/taon (€2,660.32/buwan), bago tax credits.", "Tugma ba ito sa payslip ko?", "Hindi. Edad/AOW bands, tax credits, detalye ng payroll at personal na kalagayan ay wala sa modelo. Ang 0% na hiwalay na kontribusyon ay hindi nangangahulugang walang aktuwal na obligasyon."],
    vat: ["Ilagay ang halagang bago ang buwis o kabuuan, piliin ang direksiyon at ilagay ang BTW rate ng transaksiyon. Suriin nang hiwalay ang produkto, exemption, reverse charge at teritoryo.", "BTW sa net=net×ipinasok na rate/100; kabuuan=net+BTW. Kung kasama na ang buwis, net=kabuuan/(1+ipinasok na rate/100).", "Ang €1,000 net sa ipinasok na 21% ay nagbibigay ng €210 BTW at €1,210 kabuuan. Kapag inalis ang 21% mula sa €1,210, €1,000 net ang natitira.", "21% ba ang para sa lahat ng transaksiyon sa Netherlands?", "Hindi. 21% ang pangkalahatan; 9% ang ilang produkto/serbisyo, 0% ang ilang cross-border case, at may exemptions. Hindi kinikilala ng tool ang klasipikasyon."],
    ruling: ["Ilagay ang taunang sahod at porsiyento ng scenario. Porsiyentong kalkulasyon ito, hindi pasya sa eligibility; €78,600 ang naka-configure na buong-taong cap para sa 2026.", "Posibleng allowance=min(taunang sahod×ipinasok na rate/100, €78,600); natitirang sahod=sahod−allowance. Ipinapalagay ng engine ang buong taon.", "Sa €80,000 at ipinasok na 30%, €24,000 ang modelong allowance at €56,000 ang natitira. Hindi nito kinukumpirma ang approval o eligibility.", "Kinukumpirma ba ng resulta na kwalipikado ako sa 30% facility?", "Hindi. Karaniwang 2026 salary norm ay lampas €48,013; mas mababa ang norm para sa ilang master's graduate na wala pang 30 at may eksepsiyon ang kwalipikadong researcher. Mahalaga rin ang recruitment mula abroad, residence history, joint employer application at balidong desisyon; hindi sinusuri o ipinaprorata ng tool ang mga ito."],
  },
  bn: {
    salary: ["বার্ষিক বা মাসিক মোট বেতন এবং আলাদা অবদান-অনুমান থাকলে দিন। ২০২৬ সালে AOW বয়সের নিচে Box 1-এর প্রথম ধাপে জাতীয় বিমা প্রিমিয়াম অন্তর্ভুক্ত; মডেল বয়স বা কর-ক্রেডিট সমন্বয় করে না।", "মডেল বার্ষিক কর=€38,883 পর্যন্ত 35.75% + €78,426 পর্যন্ত 37.56% + অতিরিক্ত অংশে 49.5% (২০২৬, AOW বয়সের নিচে)। আনুমানিক নিট=মোট−কর−প্রদত্ত অবদান।", "বার্ষিক €50,000 এবং আলাদা অবদান 0% হলে মডেল কর €18,076.22, নিট €31,923.78/বছর (€2,660.32/মাস); কর-ক্রেডিটের আগে।", "এটি কি বেতন স্লিপের সঙ্গে মিলবে?", "না। বয়স/AOW ধাপ, কর-ক্রেডিট, বেতনের উপাদান ও ব্যক্তিগত অবস্থা মডেল করা হয় না। আলাদা অবদান 0% মানে বাস্তবে কোনো অবদান দিতে হয় না—এমন নয়।"],
    vat: ["কর-পূর্ব অঙ্ক বা মোট দিন, দিক নির্বাচন করুন এবং লেনদেনের BTW হার লিখুন। পণ্য শ্রেণি, অব্যাহতি, reverse charge ও অঞ্চল আলাদাভাবে যাচাই করুন।", "নিটের ওপর BTW=নিট×প্রদত্ত হার/100; মোট=নিট+BTW। করসহ অঙ্কে নিট=মোট/(1+প্রদত্ত হার/100)।", "€1,000 নিটে প্রদত্ত 21% হলে BTW €210 এবং মোট €1,210। €1,210 থেকে 21% বাদ দিলে নিট €1,000 থাকে।", "নেদারল্যান্ডসের সব লেনদেনে কি 21%?", "না। সাধারণ হার 21%; নির্দিষ্ট পণ্য/সেবায় 9%, কিছু সীমান্ত-পার লেনদেনে 0%, এবং অব্যাহতি আছে। টুলটি শ্রেণিবিন্যাস নির্ধারণ করে না।"],
    ruling: ["বার্ষিক বেতন ও দৃশ্যকল্পের হার দিন। এটি অনুপাতের হিসাব, যোগ্যতার সিদ্ধান্ত নয়; ২০২৬ পূর্ণ বছরের কনফিগার করা সীমা €78,600।", "সম্ভাব্য করমুক্ত ভাতা=min(বার্ষিক বেতন×প্রদত্ত হার/100, €78,600); অবশিষ্ট বেতন=বেতন−ভাতা। ইঞ্জিন পূর্ণ বছর ধরে।", "€80,000 বেতন ও প্রদত্ত 30% হলে মডেল ভাতা €24,000 এবং অবশিষ্ট €56,000। এতে অনুমোদন বা যোগ্যতা নিশ্চিত হয় না।", "ফল কি 30% facility-তে যোগ্যতা নিশ্চিত করে?", "না। ২০২৬ সাধারণ বেতনসীমা €48,013-এর বেশি; ৩০ বছরের কম কিছু মাস্টার্সধারীর সীমা কম এবং যোগ্য গবেষকের ব্যতিক্রম থাকতে পারে। বিদেশ থেকে নিয়োগ, বসবাসের ইতিহাস, নিয়োগকর্তার যৌথ আবেদন ও বৈধ সিদ্ধান্তও গুরুত্বপূর্ণ; টুল শর্ত যাচাই বা আংশিক বছর অনুপাতে হিসাব করে না।"],
  },
  uk: {
    salary: ["Введіть річну або місячну зарплату брутто та окреме припущення щодо внесків, якщо потрібно. У 2026 році перша ставка Box 1 для осіб до віку AOW включає національні страхові внески; модель не коригує вік або податкові кредити.", "Модельний річний податок=35,75% до €38 883 + 37,56% до €78 426 + 49,5% понад суму (2026, до віку AOW). Орієнтовне нетто=брутто−податок−введені внески.", "За зарплати €50 000 на рік і окремого внеску 0% модельний податок €18 076,22, нетто €31 923,78/рік (€2 660,32/міс.), до податкових кредитів.", "Чи збігатиметься це з розрахунковим листом?", "Ні. Вік/ставки AOW, кредити, складові зарплати й особисті обставини не враховані. Окремий внесок 0% не означає відсутності реальних зобов’язань."],
    vat: ["Введіть суму без податку або загальну, виберіть напрям і ставку BTW для операції. Категорію товару, звільнення, reverse charge і територію перевірте окремо.", "BTW на нетто=нетто×введена ставка/100; загальна=нетто+BTW. Для суми з податком нетто=загальна/(1+введена ставка/100).", "€1 000 без BTW за введених 21% дають €210 BTW і €1 210 разом. Виділення 21% із €1 210 повертає €1 000 без податку.", "Чи всі операції в Нідерландах оподатковуються 21%?", "Ні. Загальна ставка 21%; для окремих товарів/послуг — 9%, для деяких транскордонних випадків — 0%, також є звільнення. Інструмент не визначає категорію."],
    ruling: ["Введіть річну зарплату й відсоток сценарію. Це арифметичне моделювання, а не перевірка права; налаштована межа за повний 2026 рік — €78 600.", "Потенційна неоподатковувана виплата=min(річна зарплата×введена ставка/100, €78 600); залишок зарплати=зарплата−виплата. Рік вважається повним.", "За зарплати €80 000 і введених 30% модельна виплата €24 000, залишок €56 000. Це не підтверджує схвалення чи право.", "Чи підтверджує результат право на режим 30%?", "Ні. Загальний поріг зарплати 2026 року перевищує €48 013; для деяких магістрів до 30 років поріг нижчий, а кваліфіковані дослідники можуть мати виняток. Важливі також найм з-за кордону, історія проживання, спільна заява роботодавця й чинне рішення; інструмент не перевіряє умови та не пропорціонує неповний рік."],
  },
  ms: {
    salary: ["Masukkan gaji kasar tahunan atau bulanan dan andaian caruman berasingan jika perlu. Pada 2026, kadar Box 1 pertama bagi mereka di bawah umur AOW merangkumi premium insurans nasional; model tidak melaras umur atau kredit cukai.", "Cukai tahunan model=35.75% hingga €38,883 + 37.56% hingga €78,426 + 49.5% lebihan (2026, sebelum umur AOW). Bersih anggaran=kasar−cukai−caruman yang dimasukkan.", "Gaji €50,000 setahun dan caruman berasingan 0% menghasilkan cukai model €18,076.22, bersih €31,923.78/tahun (€2,660.32/bulan), sebelum kredit cukai.", "Adakah ini sama dengan slip gaji?", "Tidak. Umur/jalur AOW, kredit cukai, komponen gaji dan keadaan peribadi tidak dimodelkan. Caruman berasingan 0% bukan bermakna tiada caruman sebenar perlu dibayar."],
    vat: ["Masukkan amaun sebelum cukai atau jumlah, pilih arah dan nyatakan kadar BTW transaksi. Kategori barang, pengecualian, reverse charge dan wilayah perlu disemak berasingan.", "BTW atas bersih=bersih×kadar dimasukkan/100; jumlah=bersih+BTW. Bagi jumlah termasuk cukai, bersih=jumlah/(1+kadar dimasukkan/100).", "€1,000 bersih pada 21% yang dimasukkan memberi €210 BTW dan jumlah €1,210. Mengasingkan 21% daripada €1,210 mengembalikan bersih €1,000.", "Adakah semua transaksi Belanda dikenakan 21%?", "Tidak. Kadar umum 21%; barang/perkhidmatan tertentu 9%, sesetengah urus niaga rentas sempadan 0%, dan terdapat pengecualian. Alat tidak mengelaskan transaksi."],
    ruling: ["Masukkan gaji tahunan dan peratus senario. Ini kiraan kadar, bukan keputusan kelayakan; had tahun penuh 2026 yang dikonfigurasikan ialah €78,600.", "Elaun berpotensi=min(gaji tahunan×kadar dimasukkan/100, €78,600); baki gaji=gaji−elaun. Enjin mengandaikan setahun penuh.", "Dengan gaji €80,000 dan 30% dimasukkan, elaun model €24,000 dan baki €56,000. Ini tidak mengesahkan kelulusan atau kelayakan.", "Adakah hasil ini mengesahkan kelayakan kemudahan 30%?", "Tidak. Ambang gaji umum 2026 melebihi €48,013; sesetengah graduan sarjana bawah 30 tahun mempunyai ambang lebih rendah dan penyelidik layak mungkin dikecualikan. Pengambilan dari luar negara, sejarah kediaman, permohonan bersama majikan dan keputusan sah turut penting; alat tidak menguji syarat atau memprorata tahun separa."],
  },
  sv: {
    salary: ["Ange års- eller månadslön brutto och eventuellt ett separat antagande om avgifter. År 2026 inkluderar första Box 1-skiktet för personer under AOW-ålder nationella försäkringspremier; modellen justerar inte för ålder eller skatteavdrag.", "Modellerad årsskatt=35,75% till €38 883 + 37,56% till €78 426 + 49,5% över (2026, före AOW-ålder). Beräknad nettolön=brutto−skatt−angiven avgift.", "Vid €50 000 årslön och separat avgift 0% blir modellskatten €18 076,22 och nettot €31 923,78/år (€2 660,32/mån), före skatteavdrag.", "Blir resultatet samma som lönebeskedet?", "Nej. Ålder/AOW-skikt, skatteavdrag, löneposter och personliga förhållanden modelleras inte. Separat avgift 0% betyder inte att inga verkliga avgifter ska betalas."],
    vat: ["Ange belopp exklusive moms eller totalsumma, välj riktning och ange transaktionens BTW-sats. Produktklass, undantag, omvänd skattskyldighet och territorium måste kontrolleras separat.", "BTW på netto=netto×angiven sats/100; totalt=netto+BTW. För belopp inklusive skatt är netto=total/(1+angiven sats/100).", "€1 000 netto med angivna 21% ger €210 BTW och €1 210 totalt. Om 21% tas ut ur €1 210 blir nettot €1 000.", "Gäller 21% för varje nederländsk transaktion?", "Nej. Standardsatsen är 21%; vissa varor/tjänster har 9%, vissa gränsöverskridande fall 0% och undantag finns. Verktyget klassificerar inte transaktionen."],
    ruling: ["Ange årslön och scenarioandel. Det är procentuell beräkning, inte behörighetsprövning; den konfigurerade helårsgränsen för 2026 är €78 600.", "Möjligt skattefritt tillägg=min(årslön×angiven andel/100, €78 600); återstående lön=lön−tillägg. Motorn antar ett helt år.", "Vid €80 000 och angivna 30% är modellens tillägg €24 000 och återstående lön €56 000. Det bekräftar inte godkännande eller behörighet.", "Bekräftar resultatet min rätt till 30%-regeln?", "Nej. Den allmänna lönenormen 2026 överstiger €48 013; vissa masterexaminerade under 30 har lägre norm och kvalificerade forskare kan undantas. Rekrytering från utlandet, bosättningshistorik, gemensam arbetsgivaransökan och giltigt beslut spelar också roll; verktyget kontrollerar inte detta eller proportionerar delår."],
  },
  cs: {
    salary: ["Zadejte roční nebo měsíční hrubou mzdu a případný samostatný předpoklad příspěvku. V roce 2026 zahrnuje první pásmo Box 1 pro osoby před věkem AOW národní pojistné; model neupravuje věk ani daňové slevy.", "Modelová roční daň=35,75% do €38 883 + 37,56% do €78 426 + 49,5% nad limit (2026, před věkem AOW). Odhad čisté mzdy=hrubá−daň−zadaný příspěvek.", "Při roční mzdě €50 000 a odděleném příspěvku 0% činí modelová daň €18 076,22 a čistá mzda €31 923,78/rok (€2 660,32/měsíc), před slevami.", "Bude výsledek stejný jako na výplatní pásce?", "Ne. Věk/pásma AOW, slevy, mzdové položky a osobní okolnosti model neřeší. Samostatný příspěvek 0% neznamená, že ve skutečnosti nejsou žádné odvody."],
    vat: ["Zadejte částku bez daně nebo celkovou částku, zvolte směr a sazbu BTW pro transakci. Druh zboží, osvobození, reverse charge a území ověřte samostatně.", "BTW z netto=netto×zadaná sazba/100; celkem=netto+BTW. U částky včetně daně netto=celkem/(1+zadaná sazba/100).", "Netto €1 000 při zadaných 21% dává BTW €210 a celkem €1 210. Po odečtení 21% z €1 210 zůstane netto €1 000.", "Platí 21% pro každou nizozemskou transakci?", "Ne. Obecná sazba je 21%; vybrané zboží/služby mají 9%, některé přeshraniční případy 0% a existují osvobození. Nástroj transakci nezařazuje."],
    ruling: ["Zadejte roční mzdu a procento scénáře. Jde o výpočet poměru, nikoli posouzení nároku; nastavený limit za celý rok 2026 je €78 600.", "Možný nezdaněný příspěvek=min(roční mzda×zadaná sazba/100, €78 600); zbytek mzdy=mzda−příspěvek. Výpočet předpokládá celý rok.", "Při mzdě €80 000 a zadaných 30% činí modelový příspěvek €24 000 a zbytek €56 000. Nejde o potvrzení schválení ani nároku.", "Potvrzuje výsledek nárok na 30% režim?", "Ne. Obecná mzdová hranice pro rok 2026 přesahuje €48 013; někteří absolventi magisterského studia mladší 30 let mají nižší hranici a kvalifikovaní výzkumníci mohou mít výjimku. Záleží i na náboru ze zahraničí, historii pobytu, společné žádosti zaměstnavatele a platném rozhodnutí; nástroj podmínky nekontroluje ani nekrátí neúplný rok."],
  },
  ro: {
    salary: ["Introdu salariul brut anual sau lunar și, dacă este cazul, o ipoteză separată pentru contribuții. În 2026, prima cotă Box 1 pentru persoanele sub vârsta AOW include primele naționale; modelul nu ajustează vârsta sau creditele fiscale.", "Impozit anual modelat=35,75% până la €38.883 + 37,56% până la €78.426 + 49,5% peste (2026, sub vârsta AOW). Net estimat=brut−impozit−contribuția introdusă.", "La €50.000 anual și contribuție separată 0%: impozit modelat €18.076,22 și net €31.923,78/an (€2.660,32/lună), înainte de credite fiscale.", "Rezultatul va coincide cu fluturașul?", "Nu. Vârsta/tranșele AOW, creditele, elementele salariale și situația personală nu sunt modelate. Contribuția separată 0% nu înseamnă că nu există obligații reale."],
    vat: ["Introdu suma fără TVA sau totalul, alege direcția și indică rata BTW a tranzacției. Categoria produsului, scutirile, taxarea inversă și teritoriul trebuie verificate separat.", "BTW la net=net×rata introdusă/100; total=net+BTW. Pentru suma cu taxă inclusă, net=total/(1+rata introdusă/100).", "€1.000 net la 21% introdus generează €210 BTW și €1.210 total. Extragerea a 21% din €1.210 redă €1.000 net.", "Se aplică 21% tuturor tranzacțiilor olandeze?", "Nu. Rata generală este 21%; unele bunuri/servicii au 9%, anumite situații transfrontaliere au 0%, iar unele operațiuni sunt scutite. Instrumentul nu clasifică tranzacția."],
    ruling: ["Introdu salariul anual și procentul scenariului. Este un calcul proporțional, nu o decizie de eligibilitate; plafonul integral configurat pentru 2026 este €78.600.", "Indemnizație potențială=min(salariu anual×rata introdusă/100, €78.600); salariu rămas=salariu−indemnizație. Motorul presupune anul complet.", "La salariu €80.000 și 30% introdus, indemnizația modelată este €24.000, iar restul €56.000. Nu confirmă aprobarea sau eligibilitatea.", "Rezultatul confirmă dreptul la facilitatea de 30%?", "Nu. Pragul salarial general din 2026 depășește €48.013; unele persoane cu master sub 30 de ani au prag redus, iar cercetătorii eligibili pot fi exceptați. Contează și recrutarea din străinătate, istoricul de rezidență, cererea comună cu angajatorul și decizia valabilă; instrumentul nu verifică aceste condiții și nu proratează anul parțial."],
  },
  el: {
    salary: ["Εισαγάγετε ετήσιο ή μηνιαίο μικτό μισθό και, αν χρειάζεται, ξεχωριστή υπόθεση εισφοράς. Το 2026 η πρώτη κλίμακα Box 1 για άτομα κάτω από την ηλικία AOW περιλαμβάνει εθνικές ασφαλιστικές εισφορές· το μοντέλο δεν προσαρμόζει ηλικία ή φορολογικές πιστώσεις.", "Μοντελοποιημένος ετήσιος φόρος=35,75% έως €38.883 + 37,56% έως €78.426 + 49,5% πάνω από αυτό (2026, πριν από ηλικία AOW). Εκτιμώμενο καθαρό=μικτό−φόρος−εισαγόμενη εισφορά.", "Με €50.000 ετήσιο μισθό και χωριστή εισφορά 0%: φόρος μοντέλου €18.076,22 και καθαρό €31.923,78/έτος (€2.660,32/μήνα), πριν από πιστώσεις.", "Θα είναι ίδιο με το εκκαθαριστικό μισθού;", "Όχι. Ηλικία/κλίμακες AOW, φορολογικές πιστώσεις, στοιχεία μισθοδοσίας και προσωπικές συνθήκες δεν μοντελοποιούνται. Χωριστή εισφορά 0% δεν σημαίνει ότι δεν οφείλονται πραγματικές εισφορές."],
    vat: ["Εισαγάγετε καθαρό ποσό ή σύνολο, επιλέξτε κατεύθυνση και συντελεστή BTW της συναλλαγής. Κατηγορία προϊόντος, απαλλαγή, αντίστροφη χρέωση και περιοχή ελέγχονται χωριστά.", "BTW σε καθαρή αξία=καθαρή×εισαγόμενος συντελεστής/100· σύνολο=καθαρή+BTW. Για ποσό με φόρο, καθαρή=σύνολο/(1+εισαγόμενος συντελεστής/100).", "Καθαρή αξία €1.000 με εισαγόμενο 21% δίνει €210 BTW και σύνολο €1.210. Αφαίρεση 21% από €1.210 επιστρέφει €1.000 καθαρά.", "Ισχύει 21% για κάθε ολλανδική συναλλαγή;", "Όχι. Ο γενικός συντελεστής είναι 21%, ορισμένα αγαθά/υπηρεσίες έχουν 9%, κάποιες διασυνοριακές περιπτώσεις 0% και υπάρχουν απαλλαγές. Το εργαλείο δεν ταξινομεί τη συναλλαγή."],
    ruling: ["Εισαγάγετε ετήσιο μισθό και ποσοστό σεναρίου. Είναι αριθμητική ποσοστού, όχι έλεγχος δικαιώματος· το διαμορφωμένο πλήρες ετήσιο όριο 2026 είναι €78.600.", "Πιθανή αφορολόγητη παροχή=min(ετήσιος μισθός×εισαγόμενο ποσοστό/100, €78.600); υπόλοιπο μισθού=μισθός−παροχή. Ο μηχανισμός υποθέτει πλήρες έτος.", "Με €80.000 και εισαγόμενο 30%, η μοντελοποιημένη παροχή είναι €24.000 και το υπόλοιπο €56.000. Δεν επιβεβαιώνει έγκριση ή δικαίωμα.", "Επιβεβαιώνει το αποτέλεσμα δικαίωμα στο καθεστώς 30%;", "Όχι. Το γενικό μισθολογικό όριο 2026 υπερβαίνει τα €48.013· ορισμένοι κάτοχοι μεταπτυχιακού κάτω των 30 έχουν χαμηλότερο όριο, ενώ επιλέξιμοι ερευνητές μπορεί να εξαιρούνται. Σημασία έχουν πρόσληψη από το εξωτερικό, ιστορικό κατοικίας, κοινή αίτηση εργοδότη και έγκυρη απόφαση· το εργαλείο δεν ελέγχει όρους ούτε αναλογεί μερικό έτος."],
  },
};

